use super::*;
use crate::money::{sum, Money};

/// The heaviest run of `days` consecutive days in the window — where a month-level view goes blind.
///
/// Every window STARTS on a real obligation, because a heavy run always begins at one; sliding day by
/// day over an empty calendar would cost far more and find the same answer.
pub fn heaviest_window(c: &ObligationCalendar, days: i64) -> Option<Window> {
    let first = c.obligations.first()?;
    let currency = first.amount.currency;
    let mut best: Option<Window> = None;
    for o in &c.obligations {
        let end = add_days(&o.date, days - 1);
        let amounts: Vec<Money> = due_between(c, &o.date, &end).iter().map(|x| x.amount).collect();
        let Ok(total) = sum(&amounts, currency) else { continue };
        if best.as_ref().is_none_or(|b| total.minor > b.total.minor) {
            best = Some(Window { from: o.date.clone(), to: end, total });
        }
    }
    best
}
